// TEC-474 (F5-02c): fleet portal reads. Every query is bounded by the
// signed-in user's fleet (fleet_org_id) and by dealer_ids: the dealers the
// fleet worked with (an active or ended link) whose fleet module is still
// on. A dealer that turns the module off drops out of dealer_ids, so its
// services, warranties, appointments and cari disappear from the portal
// (nothing is deleted).
// Vehicles of the fleet with the last service, the service count, the
// active warranty count and the latest active warranty end of the visible
// dealers. Sort keys plate | last_service_at | warranty_until, default plate.
func (q *Queries) ListFleetPortalVehicles(ctx context.Context, arg ListFleetPortalVehiclesParams) ([]ListFleetPortalVehiclesRow, error) {
	rows, err := q.db.Query(ctx, listFleetPortalVehicles,
		arg.HasActiveWarranty,
		arg.SortDesc,
		arg.SortKey,
		arg.OffsetCount,
		arg.LimitCount,
		arg.DealerIds,
		arg.FleetOrgID,
		arg.VehicleUuid,
		arg.Q,
		arg.QPlate,
		arg.CarBrandUuids,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListFleetPortalVehiclesRow{}
	for rows.Next() {
		var i ListFleetPortalVehiclesRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.Plate,
			&i.PlateCountry,
			&i.Vin,
			&i.ModelYear,
			&i.CreatedAt,
			&i.CarBrandUuid,
			&i.CarBrandName,
			&i.CarModelUuid,
			&i.CarModelName,
			&i.LastServiceAt,
			&i.ServiceCount,
			&i.ActiveWarrantyCount,
			&i.WarrantyUntil,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listFleetPortalWarranties = `-- name: ListFleetPortalWarranties :many
WITH fw AS (
    SELECT w.id, w.uuid, w.public_code, w.start_at, w.end_at,
           (CASE WHEN w.status = 'void' THEN 'void'
                 WHEN w.status = 'active' AND w.end_at > NOW() THEN 'active'
                 ELSE 'expired' END)::text AS state,
           p.uuid AS product_uuid, p.sku AS product_sku, p.name AS product_name,
           s.uuid AS service_uuid, s.service_no,
           o.uuid AS organization_uuid, o.name AS organization_name, o.type AS organization_type,
           v.uuid AS vehicle_uuid, v.plate
    FROM warranties w
    JOIN vehicles v ON v.id = w.vehicle_id
    JOIN products p ON p.id = w.product_id
    JOIN services s ON s.id = w.service_id
    JOIN organizations o ON o.id = w.organization_id
    WHERE v.fleet_org_id = $6::bigint
      AND w.organization_id = ANY ($7::bigint[])
      AND ($8::bigint IS NULL OR w.vehicle_id = $8::bigint)
      AND (COALESCE(cardinality($9::uuid[]), 0) = 0 OR o.uuid = ANY ($9::uuid[]))
      AND ($10::text IS NULL
           OR v.plate ILIKE '%' || $10::text || '%'
           OR w.public_code ILIKE '%' || $10::text || '%'
           OR p.name ILIKE '%' || $10::text || '%')
)
SELECT id, uuid, public_code, start_at, end_at, state, product_uuid, product_sku, product_name, service_uuid, service_no, organization_uuid, organization_name, organization_type, vehicle_uuid, plate FROM fw
WHERE COALESCE(cardinality($1::text[]), 0) = 0 OR fw.state = ANY ($1::text[])
ORDER BY
  CASE WHEN NOT $2::bool AND $3::text = 'end_at' THEN fw.end_at END ASC,
  CASE WHEN $2::bool AND $3::text = 'end_at' THEN fw.end_at END DESC,
  CASE WHEN NOT $2::bool AND $3::text = 'start_at' THEN fw.start_at END ASC,
  CASE WHEN $2::bool AND $3::text = 'start_at' THEN fw.start_at END DESC,
  CASE WHEN $2::bool THEN fw.id END DESC,
  fw.id ASC
LIMIT $5 OFFSET $4
`

