// Warranties on the fleet's vehicles issued by the visible dealers. state
// is the effective status: active (active and not past end_at), expired
// (expired, or active past end_at) or void. Sort keys end_at | start_at,
// default end_at.
func (q *Queries) ListFleetPortalWarranties(ctx context.Context, arg ListFleetPortalWarrantiesParams) ([]ListFleetPortalWarrantiesRow, error) {
	rows, err := q.db.Query(ctx, listFleetPortalWarranties,
		arg.States,
		arg.SortDesc,
		arg.SortKey,
		arg.OffsetCount,
		arg.LimitCount,
		arg.FleetOrgID,
		arg.DealerIds,
		arg.VehicleID,
		arg.DealerUuids,
		arg.Q,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListFleetPortalWarrantiesRow{}
	for rows.Next() {
		var i ListFleetPortalWarrantiesRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.PublicCode,
			&i.StartAt,
			&i.EndAt,
			&i.State,
			&i.ProductUuid,
			&i.ProductSku,
			&i.ProductName,
			&i.ServiceUuid,
			&i.ServiceNo,
			&i.OrganizationUuid,
			&i.OrganizationName,
			&i.OrganizationType,
			&i.VehicleUuid,
			&i.Plate,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
